function openWindow(key,title,width=600,height=420,opts={}){if(windows.has(key)){const w=windows.get(key);if(!opts.refresh)focusWindow(w);return w}const space=$('#workspace');if(!space)return;const n=windows.size;const initial=opts.initial;const rect=space.getBoundingClientRect();const x=opts.x??(initial?Math.min(750,Math.max(24,rect.width-width-28)):40+(n%5)*30),y=opts.y??(initial?115:85+(n%5)*22);const el=document.createElement('section');el.className='window';el.dataset.key=key;el.tabIndex=-1;el.setAttribute('aria-label',title);el.innerHTML=`<header class="window-title"><span class="caption"><span style="color:var(--accent)">◈</span><strong>${esc(title)}</strong></span><span class="row" style="gap:0"><button data-fold aria-label="창 접기">−</button><button data-close aria-label="창 닫기">×</button></span></header><div class="window-body"></div><div class="resize-grip" role="button" tabindex="0" aria-label="창 크기 조절"></div>`;space.append(el);const w={key,title,el,body:$('.window-body',el),x,y,width:Math.min(width,rect.width),height:Math.min(height,rect.height-20),folded:false,meta:opts.meta||{}};windows.set(key,w);clampWindow(w);focusWindow(w);$('[data-close]',el).onclick=()=>closeWindow(key);$('[data-fold]',el).onclick=()=>{w.folded=!w.folded;el.classList.toggle('folded',w.folded);$('[data-fold]',el).textContent=w.folded?'+':'−';clampWindow(w);saveLayouts()};el.addEventListener('pointerdown',()=>focusWindow(w));setupWindowDrag(w);$('.resize-grip',el).onkeydown=e=>{if(e.key.startsWith('Arrow')){e.preventDefault();w.width+=e.key==='ArrowRight'?20:e.key==='ArrowLeft'?-20:0;w.height+=e.key==='ArrowDown'?20:e.key==='ArrowUp'?-20:0;clampWindow(w);saveLayouts()}};return w}
function placeWindow(w){Object.assign(w.el.style,{left:w.x+'px',top:w.y+'px',width:w.width+'px',height:w.height+'px'})}
function focusWindow(w){w.el.style.zIndex=++z;$$('.window.active').forEach(el=>el.classList.remove('active'));w.el.classList.add('active')}
function clampWindow(w){const s=$('#workspace');if(!s)return;const width=s.clientWidth,height=Math.max(1,s.clientHeight-94);w.width=Math.max(Math.min(260,width),Math.min(w.width,width));w.height=Math.max(Math.min(160,height),Math.min(w.height,height));w.x=Math.max(0,Math.min(w.x,width-w.width));w.y=Math.max(0,Math.min(w.y,height-(w.folded?45:w.height)));placeWindow(w)}
function clampWindows(){windows.forEach(clampWindow)}
function setupWindowDrag(w){const move=(e,resize=false)=>{if(e.target.closest('button')&&!resize)return;if(e.button!==0)return;e.preventDefault();const sx=e.clientX,sy=e.clientY,start={x:w.x,y:w.y,width:w.width,height:w.height};const handle=e.currentTarget;handle.setPointerCapture(e.pointerId);const onMove=ev=>{const dx=ev.clientX-sx,dy=ev.clientY-sy;if(resize){w.width=start.width+dx;w.height=start.height+dy}else{w.x=start.x+dx;w.y=start.y+dy;snapWindow(w)}clampWindow(w)};const end=()=>{handle.removeEventListener('pointermove',onMove);handle.removeEventListener('pointerup',end);handle.removeEventListener('pointercancel',end);saveLayouts()};handle.addEventListener('pointermove',onMove);handle.addEventListener('pointerup',end);handle.addEventListener('pointercancel',end)};$('.window-title',w.el).onpointerdown=e=>move(e);$('.resize-grip',w.el).onpointerdown=e=>move(e,true)}
function snapWindow(w){const s=$('#workspace'),h=w.folded?45:w.height;const xs=[0,s.clientWidth-w.width],ys=[0,s.clientHeight-h];windows.forEach(other=>{if(other===w)return;const oh=other.folded?45:other.height;if(w.y<other.y+oh+16&&w.y+h>other.y-16)xs.push(other.x+other.width+8,other.x-w.width-8,other.x);if(w.x<other.x+other.width+16&&w.x+w.width>other.x-16)ys.push(other.y+oh+8,other.y-h-8,other.y)});const x=xs.find(x=>Math.abs(w.x-x)<14),y=ys.find(y=>Math.abs(w.y-y)<14);if(x!==undefined)w.x=x;if(y!==undefined)w.y=y}
function closeWindow(key){const w=windows.get(key);if(!w)return;if(key==='source'){w.el.hidden=true;saveLayouts();return;}if(key.startsWith('editor-')){w.el.hidden=true;saveLayouts();return;}w.el.remove();windows.delete(key);saveLayouts();}
function saveLayouts(){if(!current)return;try{localStorage.setItem('confectory-layout-'+current.projectId,JSON.stringify([...windows.values()].map(({key,x,y,width,height,folded,el})=>({key,x,y,width,height,folded,hidden:el.hidden}))));}catch{}}
function toast(text){$('#status').textContent=text;}
function drawWork(){windows.clear();draft=null;dirty=false;$('#app').innerHTML=`<div class="work"><header class="topbar"><div class="row">${brand()}<span class="muted">/</span><span id="title" class="project-title"></span></div><div class="right"><small>로컬 작업실</small></div></header><div class="work-body"><aside class="home-side"><div class="participant-section-heading"><span id="agent-summary">⌘ AGENT · 미연결</span></div><p class="consumer-note">실제 AI 계정 연결은 보류되어 있습니다.</p><div class="participant-section-heading">☆ HELPER</div><div class="consumer-portraits">${['lumi','tori','vex'].map((name,i)=>`<figure><img src="assets/${name}.png" alt="${['루미','토리','벡스'][i]} 참고 초상"><figcaption>${['루미','토리','벡스'][i]}<br>참고 초상</figcaption></figure>`).join('')}</div><div id="helper-summary"></div><button data-operation id="helpers">Helper 관리</button><button data-operation id="connections">AI 연결 팩</button><div id="worker-summary"></div></aside><div class="work-main-column"><main class="workspace" id="workspace"><div class="space-label"><span id="workspace-label"></span></div><div class="bubble-dock"><button class="bubble" data-operation id="yogi" title="선택 의미 객체 패키지">📦<span class="dock-label">YogiBox</span></button><button class="bubble" data-operation id="augment" title="증강 제안과 작업 흐름">⇈<span class="dock-label">증강</span></button><button class="bubble" disabled title="신문고 연결 준비 중">📫<span class="dock-label">신문고</span></button><button class="bubble" id="build-target" data-operation title="선언된 빌드·실행 대상">🛠️<span class="dock-label">빌드</span></button><button class="bubble" data-operation id="run" title="현재 Confirm한 프로젝트 실행">▶<span class="dock-label">실행</span></button><button class="bubble nav" id="nav" aria-label="프로젝트 브라우저">≡<span class="dock-label">프로젝트 브라우저</span></button></div></main><section class="chatbar"><div class="chat-tabs"><button id="chat">프로젝트 대화</button><button id="logs-tab" class="selected">Logs</button></div><div id="status" role="status">Connecting</div><div id="chat-inner" class="chat-inner" hidden></div><pre id="execution-logs" class="consumer-logs"></pre><div class="consumer-tools"><button id="objects-refresh">Objects</button><button id="reconnect">Reconnect view</button></div></section></div></div></div>`;bindCommon();$('#helpers').onclick=()=>work(async()=>{await view.call('helperList',{});showHelpers();},'로컬 Helper 목록');$('#connections').onclick=()=>work(async()=>{await view.call('connections',{});showConnections();},'AI 연결 팩 목록');$('#augment').onclick=()=>work(async()=>{await view.call('augmentShow',{});showAugment();},'증강 상태');$('#chat').onclick=showChat;$('#logs-tab').onclick=()=>{$('#chat-inner').hidden=true;$('#execution-logs').hidden=false;$('#chat').classList.remove('selected');$('#logs-tab').classList.add('selected');};$('#yogi').onclick=()=>work(async()=>{await view.call('yogi',{action:'show'});showYogi();},'로컬 YogiBox');$('#nav').onclick=()=>{browser();};$('#build-target').onclick=showTargets;$('#run').onclick=()=>work(()=>view.call(['building','running'].includes(current.executionState)?'stopProject':'runProject',{target:targetChoices.get(current.projectId)||current.runTarget}),'Execution request handled');$('.brand').onclick=()=>work(()=>view.call('leaveProject',{}),'Project hidden; work continues');}
function controls(){for(const b of $$('[data-operation],[data-review-id],[data-id],[data-project],#open-local,#objects-refresh,#reconnect,#object-kind'))b.disabled=busy||b.dataset.supported==='false';$('#source')?.toggleAttribute('disabled',busy);for(const input of $$('[data-schema-field]'))input.disabled=busy||input.dataset.supported==='false';if($('#run')){$('#run').disabled=busy||!current?.canRun;$('#run').innerHTML=['building','running'].includes(current.executionState)?'■<span class="dock-label">중지</span>':'▶<span class="dock-label">실행</span>';}if($('#open-local'))$('#open-local').disabled=busy||!globalThis.confectoryWebUI?.pickFile;if($('#create-project'))$('#create-project').disabled=busy||!globalThis.confectoryWebUI?.createProject;previewControls();if($('#confirm'))$('#confirm').disabled=busy||current.review?.status!=='ready'||current.review?.token!==$('#confirm').dataset.token;$('.brand')?.toggleAttribute('disabled',busy);}
function browser(){const w=openWindow('browser','프로젝트 브라우저',685,470,{x:28,y:85});w.body.innerHTML='<div class="browser-tabs"><button class="selected">의미 객체</button><button id="inspect-object" data-operation>선택 객체 편집</button><button id="advanced-source" data-operation>고급 소스 편집</button><button id="keep-properties" data-operation>속성창 유지</button><button id="keep-source" data-operation>고급 소스창 유지</button></div><div class="consumer-tools"><select id="object-kind" aria-label="의미 객체 종류"><option value="object">객체</option><option value="schema">스키마</option><option value="module">모듈</option><option value="function">기능</option><option value="implementation">구현</option><option value="">전체 선언·고급 소스</option></select><input id="object-query" maxlength="256" placeholder="객체 ID 검색"><button data-operation id="object-search">검색</button></div><div class="consumer-tools"><select id="new-declaration-kind" aria-label="새 의미 선언 종류"><option value="object">객체</option><option value="schema">스키마</option></select><input id="new-declaration-name" maxlength="64" placeholder="새 선언 이름"><button data-operation id="new-declaration">선언 초안 만들기</button><button data-operation id="review-group">선택한 변경 Review</button></div><div id="retained-editors"></div><div id="objects" class="consumer-objects"></div><div class="consumer-tools"><button data-operation id="previous">Previous</button><button data-operation id="next">Next</button></div>';$('#new-declaration').onclick=()=>work(async()=>{const name=$('#new-declaration-name').value.trim();if(!/^[A-Za-z_][A-Za-z0-9_]*$/.test(name))throw Error('영문·숫자·밑줄로 선언 이름을 입력하세요.');await view.call('createDeclaration',{id:current.namespace+'::'+name,kind:$('#new-declaration-kind').value});await view.call('schema',{id:current.draft.id});showSchema();},'새 선언은 공유 초안입니다. 최종 반영에는 선언과 프로젝트 등록 변경을 함께 Review / Confirm하세요.');$('#review-group').onclick=()=>work(async()=>{if(dirty||[...schemaInputs.keys()].some(key=>key.startsWith(current.projectId+'|'))||[...viewInputs.keys()].some(key=>key.startsWith(current.projectId+'|')))throw Error('미적용 입력을 먼저 적용하세요.');const ids=[...(reviewSelections.get(current.projectId)||[])];if(!ids.length)throw Error('검토할 실제 선언·등록 변경을 선택하세요.');await view.call('reviewGroup',{ids,target:targetChoices.get(current.projectId)||current.runTarget});showReview();},'선택한 변경 검토 · 아직 최종 반영 없음');$('#object-search').onclick=()=>act('objects',{kind:$('#object-kind').value,query:$('#object-query').value});$('#object-kind').onchange=$('#object-search').onclick;$('#keep-properties').onclick=()=>keepEditor('properties');$('#keep-source').onclick=()=>keepEditor('source');$('#previous').onclick=()=>act('page',{page:Math.max(0,(current.page||0)-1)});$('#next').onclick=()=>act('page',{page:(current.page||0)+1});$('#advanced-source').onclick=()=>work(async()=>{await view.call('sourceUnits',{});const source=windows.get('source');if(source){source.el.hidden=false;focusWindow(source);}},'고급 소스 탐색');$('#inspect-object').onclick=()=>work(async()=>{if(dirty)throw Error('Apply source input before inspecting another view');await view.call('schema',{id:current.draft.id});showSchema();},'선택 객체 스키마');renderObjects();renderRetainedEditors();controls();}
function renderObjects(){if(!$('#objects')||!current)return;const scope=current.projectId,selected=reviewSelections.get(scope)||new Set();$('#objects').replaceChildren(...current.units.map(unit=>{const row=document.createElement('div');row.className='consumer-object-row';const check=document.createElement('input');check.type='checkbox';check.dataset.reviewId=unit.id;check.setAttribute('aria-label',unit.id+' · Review 선택');check.checked=selected.has(unit.id);check.disabled=busy;check.onchange=()=>{if(check.checked)selected.add(unit.id);else selected.delete(unit.id);reviewSelections.set(scope,selected);};const b=document.createElement('button');b.dataset.id=unit.id;b.textContent=unit.id.split('::').at(-1)+' · '+({object:'객체',schema:'스키마',module:'모듈',function:'기능',implementation:'구현',body:'고급 소스',project:'프로젝트 등록',pack:'팩 등록'}[unit.kind]||unit.kind)+(unit.dirty?' · 초안 변경':'');b.disabled=busy;b.onclick=()=>act('select',{id:unit.id});row.append(check,b);return row;}));}
function editor(){let w=windows.get('source');if(!w){w=openWindow('source','고급 소스 작업 사본',520,450,{x:740,y:115});w.el.hidden=true;}if(!$('#source')){w.body.innerHTML='<div class="window-content"><h2 id="selection"></h2><p id="source-notice" class="small"></p><textarea id="source" class="consumer-source" aria-label="Source draft"></textarea><div class="actions"><button data-operation id="schema">스키마</button><button data-operation id="apply">Apply to shared draft</button><button data-operation id="save">Save</button><button data-operation id="review">Review</button></div><div class="editor-note">Save는 작업 사본 저장입니다. 최종 소스 반영은 별도 Review / Confirm이 필요합니다.</div></div>';$('#source').oninput=()=>dirty=true;$('#schema').onclick=()=>work(async()=>{await apply();await view.call('schema',{id:draft.id});showSchema();},'Schema loaded for selected object');$('#apply').onclick=()=>work(apply,'Shared draft updated');$('#save').onclick=()=>work(async()=>{await apply();await view.call('saveDraft',{});},'Draft saved; final sources unchanged');$('#review').onclick=()=>work(async()=>{await apply();await view.call('reviewDraft',{id:draft.id,target:targetChoices.get(current.projectId)||current.runTarget});showReview();},'Review ready; final sources unchanged');}if(current.draft&&(!draft||!dirty)){draft=current.draft;$('#source').value=draft.text;$('#selection').textContent=draft.id;w.meta.id=draft.id;}$('#source-notice').textContent=dirty&&draft?.id!==current.draft?.id?'다른 뷰에서 선택이 바뀌었습니다. 입력을 유지했습니다. 이 객체를 브라우저에서 다시 선택한 뒤 적용하세요.':'';controls();}
function keepInput(){if(current?.projectId&&$('#source'))retained.set(current.projectId,{draft,dirty,text:$('#source').value});}
function drawHome(){windows.clear();$('#app').innerHTML=`<div class="home"><header class="topbar">${brand()}<div class="right">로컬 작업실</div></header><main class="home-main"><h1>프로젝트</h1><div class="consumer-tools"><button id="open-local" ${globalThis.confectoryWebUI?.pickFile?'':'disabled'}>기존 프로젝트 열기</button><input id="new-project-title" maxlength="128" placeholder="새 프로젝트 이름" aria-label="새 프로젝트 이름"><input id="new-project-description" maxlength="4096" placeholder="프로젝트 설명" aria-label="프로젝트 설명"><button id="create-project">새 프로젝트 · 폴더 선택</button><button data-operation id="global-helpers">전역 Helper 관리</button><div id="global-helper-list"></div><button id="manage-ai" data-operation>AI 연결 팩 설정</button><div id="settings-catalog"></div><button id="reconnect">Reconnect view</button></div><div class="project-grid">${current.cards.map(card=>`<button class="project-card" data-project="${esc(card.id)}"><h2>${esc(card.title)}</h2><p>${esc(card.description||'')}</p></button>`).join('')}</div><p class="consumer-note">${current.background.map(row=>`${esc(row.title)} · ${esc(row.state)}`).join('<br>')}<br>프로젝트를 숨겨도 작업은 유지됩니다. 전체 종료는 Windows 창 닫기에서 확인합니다.</p><output id="status" role="status">Ready</output></main></div>`;$('#create-project').disabled=!globalThis.confectoryWebUI?.createProject;$('#create-project').onclick=()=>work(async()=>{const reply=await globalThis.confectoryWebUI.createProject($('#new-project-title').value,$('#new-project-description').value);if(!reply.ok)throw Error(reply.error?.code||'create_failed');if(!reply.cancelled)await recover();},'프로젝트 생성됨');$('#global-helpers').onclick=()=>work(async()=>{await view.call('globalHelpers',{});renderGlobalHelpers();},'전역 Helper 프로필 · 전송 없음');$('#manage-ai').onclick=()=>work(async()=>{await view.call('connectionCatalog',{});const container=$('#settings-catalog');container.replaceChildren(...current.connections.map(connection=>{const b=document.createElement('button');b.textContent=connection.id+' · 설정 편집';b.dataset.operation='settings';b.onclick=()=>work(async()=>{await view.call('openConnectionSettings',{connection:connection.id});await recover();await view.call('schema',{id:current.draft.id});showSchema();},'비밀값 없는 설정 팩 · 인증 없음');return b;}));},'AI 연결 팩 목록');$$('[data-project]').forEach(button=>button.onclick=()=>act('openProject',{id:button.dataset.project}));$('#open-local').onclick=()=>work(async()=>{const reply=await globalThis.confectoryWebUI.pickFile();if(!reply.ok)throw Error(reply.error?.code||'open_failed');if(!reply.cancelled)await recover();},'Ready');bindCommon();}
const view=new WebView(connectLocal(),state=>{const changed=current?.projectId!==state.projectId;if(changed)keepInput();current=state;if(!state.projectId){if(changed||!$('#settings-catalog'))drawHome();return;}if(changed){drawWork();browser();if(state.schema)showSchema();}$('#title').textContent=state.title;$('#workspace-label').textContent=state.title.toUpperCase()+' / WORKSPACE';renderObjects();editor();renderEditorViews();renderRetainedEditors();$('#execution-logs').textContent=(state.logs||[]).join('\n');if($('#chat-output'))$('#chat-output').textContent=state.aiOutput||'';$('#helper-summary').textContent=state.helperProfile?state.helperProfile.helper+' · '+state.helperProfile.speciality:'Helper를 명시적으로 선택하세요.';if(windows.has('augment')&&windows.get('augment').meta.snapshot!==JSON.stringify(state.augment))showAugment(true);if(windows.has('worker')){const panel=windows.get('worker'),row=state.workers.find(item=>item.id===panel.meta.workerId);if(row&&panel.meta.snapshot!==JSON.stringify(row))showWorker(row,true);}$('#agent-summary').textContent='⌘ AGENT · '+(state.connection?'설정 선택됨 · '+state.aiState:'미연결');$('#worker-summary').replaceChildren(...(state.workers||[]).map(worker=>{const b=document.createElement('button');b.dataset.operation='worker';const tone=['running','dispatching','awaiting-verification'].includes(worker.status)?'working':['error','interrupted','cancelled'].includes(worker.status)?'problem':'waiting';b.className='consumer-worker';b.innerHTML=`<span class="helper-worker-dot ${tone}" tabindex="0" aria-label="${esc(worker.id)} · ${esc(worker.status)}"><span class="worker-status-tooltip"><strong>${esc(worker.status)}</strong><p>${esc(worker.ownerHelper||'')} · ${esc(worker.goal||'')}</p><small>${esc(worker.progress||worker.blocker||'')}</small></span></span><small>${esc(worker.id)}</small>`;b.onclick=()=>work(async()=>{await view.call('selectWorker',{task:worker.id});showWorker(worker);},'Worker 상태');return b;}));if(changed){const input=retained.get(state.projectId);if(input?.dirty){draft=input.draft;dirty=true;windows.get('source').el.hidden=false;$('#source').value=input.text;$('#selection').textContent=draft.id;editor();}try{for(const saved of JSON.parse(localStorage.getItem('confectory-layout-'+state.projectId)||'[]')){const w=windows.get(saved.key);if(w&&[saved.x,saved.y,saved.width,saved.height].every(Number.isFinite)){Object.assign(w,{x:saved.x,y:saved.y,width:saved.width,height:saved.height,folded:saved.folded===true});w.el.classList.toggle('folded',w.folded);w.el.hidden=saved.hidden===true;clampWindow(w);}}}catch{}}});
function recover(){if(!recovering)recovering=(async()=>{keepInput();await view.dispose();await view.mount();if(windows.has('helpers')&&current.projectId)showHelpers();})().finally(()=>recovering=null);return recovering;}

async function work(action,message){if(busy)return;busy=true;controls();try{await view.update();await action();toast(message);}catch(e){if(['scope_changed','view_closed'].includes(e.message)){await recover();toast('Ready');}else toast(e.message);}finally{busy=false;controls();renderObjects();}}
function act(endpoint,input){if(dirty&&['select','objects','page'].includes(endpoint)&&!(endpoint==='select'&&input.id===draft?.id)){toast('Apply local input before changing selection');return;}return work(async()=>{await view.call(endpoint,input);if(endpoint==='select'&&!dirty&&!['body','project','pack'].includes(view.state.draft?.kind)){await view.call('schema',{id:input.id});showSchema();}},'Ready');}
async function apply(){if(!draft||!dirty)return;if(view.state.draft?.id!==draft.id)throw Error('브라우저에서 편집 중인 객체를 다시 선택하세요. 입력은 유지되었습니다.');await view.call('editDraft',{id:draft.id,text:$('#source').value,revision:draft.revision});dirty=false;draft=view.state.draft;$('#source').value=draft.text;await view.update();}
function bindCommon(){const objects=$('#objects-refresh');if(objects)objects.onclick=()=>{browser();act('objects',{});};$('#reconnect').onclick=()=>{if(dirty){toast('Apply local input before reconnecting');return;}return work(async()=>{await view.dispose();await view.mount();},'Reconnected; shared draft retained');};}
let updating=false;setInterval(async()=>{if(updating||!view.active)return;updating=true;try{await view.update();}catch(e){if(e.message==='scope_changed')await recover();else toast(e.message);}finally{updating=false;}},100);
addEventListener('resize',clampWindows);addEventListener('keydown',e=>shiftHeld=e.shiftKey);addEventListener('keyup',e=>shiftHeld=e.shiftKey);
await view.mount();toast('Ready');

function showReview(){const review=view.state.review;if(!review){toast('Review unavailable');return;}const w=openWindow('review','Source Review · 최종 반영 확인',680,490),ids=(review.units||[]).map(unit=>unit.id);w.body.innerHTML=`<div class="window-content"><h2>${esc(ids.join(' · '))}</h2><p>검토한 변경만 최종 소스에 반영합니다. 새 선언은 프로젝트 등록 변경도 함께 선택해야 합니다.</p>${review.units.map(unit=>`<details><summary>${esc(unit.id)} · 고급 소스 비교</summary><h3>Before</h3><pre class="consumer-output">${esc(unit.before)}</pre><h3>After</h3><pre class="consumer-output">${esc(unit.after)}</pre></details>`).join('')}<button id="confirm" data-operation data-token="${esc(review.token)}">Confirm · 검토한 소스 반영</button></div>`;$('#confirm').onclick=()=>work(async()=>{await view.call('confirmGroup',{token:review.token,ids});reviewSelections.delete(current.projectId);closeWindow('review');},'Source confirmed');controls();}
function showSchema(schema=view.state.schema,detached=null,refresh=false){
if(!schema){toast('Schema unavailable');return;}
 const scope=current.projectId,revision=schema.revision,w=openWindow(detached?'editor-'+detached.view:'schema','스키마 · '+schema.id,520,450,{refresh});w.meta.id=schema.id;if(detached)w.meta.view=detached.view;
 w.body.innerHTML=`<div class="window-content"><h2 data-schema-id>${esc(schema.id)}</h2><p>${esc(schema.description||'')}</p><p class="small">의미 객체 속성과 유효 스키마 · 필드 변경은 공유 초안에만 반영됩니다.</p><div data-schema-fields></div><div class="actions"><button data-operation id="semantic-save">Save · 작업 사본</button><button data-operation id="semantic-review">Review</button></div></div>`;
 $('#semantic-save',w.body).onclick=()=>work(()=>{if([...schemaInputs.keys()].some(key=>key.startsWith(current.projectId+'|'+schema.id+'|')))throw Error('필드 입력을 먼저 적용하세요. 입력은 유지됩니다.');return view.call(detached?'saveEditorView':'saveDraft',detached?{view:detached.view,id:schema.id}:{});},'Draft saved; final sources unchanged');$('#semantic-review',w.body).hidden=!!detached;$('#semantic-review',w.body).onclick=()=>work(async()=>{if(dirty||[...schemaInputs.keys()].some(key=>key.startsWith(current.projectId+'|'+schema.id+'|')))throw Error('미적용 입력을 먼저 적용하세요. 입력은 유지됩니다.');await view.call('reviewDraft',{id:schema.id,target:targetChoices.get(current.projectId)||current.runTarget});showReview();},'Review ready; final sources unchanged');
 const container=$('[data-schema-fields]',w.body);
 const metadata=Object.entries(schema.values||{}).filter(([,value])=>value!==null&&['string','number','boolean'].includes(typeof value)).map(([name,value])=>({metadata:true,name,type:typeof value,inputKind:typeof value==='string'?'text':typeof value==='boolean'?'boolean':'number',path:[name],value,writable:true}));
 if(schema.kind==='schema')renderDefinitions(schema,detached,w);
 for(const row of [...(schema.kind==='schema'?[]:schema.rows),...metadata]){
  const key=scope+'|'+schema.id+'|'+(detached?'view:'+detached.view+'|':'primary|')+(row.metadata?'metadata:':'')+JSON.stringify(row.path),pending=schemaInputs.get(key);let baseRevision=pending?.revision??revision;const field=document.createElement('div');field.className='field';
  const label=document.createElement('label');label.textContent=row.path.map(part=>typeof part==='number'?'['+part+']':part).join(' / ')+' · '+row.type;field.append(label);field.style.marginLeft=Math.min(48,(row.path.length-1)*12)+'px';
  const simple=['text','number','boolean','reference','function'].includes(row.inputKind)&&row.writable;
  const baseline=String((['reference','function'].includes(row.inputKind)?row.reference:row.value)??''),input=document.createElement('input');input.type=row.inputKind==='boolean'?'checkbox':row.inputKind==='number'?'number':'text';if(input.type==='number')input.step='any';
  input.dataset.schemaField=row.name;input.dataset.supported=String(simple);input.value=pending?.text??baseline;if(input.type==='checkbox')input.checked=input.value==='true';input.disabled=!simple;input.setAttribute('aria-label',row.name);field.append(input);
  input.oninput=()=>{if(input.type==='checkbox')input.value=String(input.checked);if(input.value===baseline)schemaInputs.delete(key);else schemaInputs.set(key,{text:input.value,revision:baseRevision});};
  if(simple){
   const applyButton=document.createElement('button');applyButton.textContent='Apply field';applyButton.dataset.operation='field';
   applyButton.onclick=()=>work(async()=>{if(dirty)throw Error('Apply source input before editing fields');if(current.projectId!==scope||(!detached&&view.state.draft?.id!==schema.id))throw Error('Schema selection changed');let value=input.type==='checkbox'?input.checked:row.inputKind==='number'?Number(input.value):['reference','function'].includes(row.inputKind)?{$ref:input.value}:input.value;if(row.inputKind==='number'&&(input.value.trim()===''||!Number.isFinite(value)))throw Error('유효한 숫자를 입력하세요. 입력은 유지됩니다.');const expected=schemaInputs.get(key)?.revision??revision;await view.call(detached?(row.metadata?'editViewMetadata':'editViewField'):row.metadata?'editMetadata':'editField',{...(detached?{view:detached.view}:{}),id:schema.id,path:row.path,field:row.name,value,revision:expected});schemaInputs.delete(key);if(!detached){await view.call('schema',{id:schema.id});showSchema();}else{w.meta.schemaStamp=null;renderEditorViews();}},'Shared field draft updated');field.append(applyButton);
   const reset=document.createElement('button');reset.textContent='현재 값으로 되돌리기';reset.dataset.operation='reset-field';reset.onclick=()=>{schemaInputs.delete(key);baseRevision=revision;input.value=baseline;if(input.type==='checkbox')input.checked=baseline==='true';};field.append(reset);
  }else{const note=document.createElement('small');note.textContent=detached&&row.metadata?'메타데이터는 기본 속성창에서 편집합니다.':row.inputKind==='list'?'아래 기존 항목을 개별 편집합니다. 삽입·재정렬은 계약 미정입니다.':row.inputKind==='group'?'아래 구성 필드를 개별 편집합니다.':'현재 경로는 읽기 전용입니다.';field.append(note);}
  container.append(field);
 }
 if(detached){const release=document.createElement('button');release.textContent='창 해제';release.dataset.operation='release-view';release.onclick=()=>work(async()=>{if([...schemaInputs.keys()].some(key=>key.startsWith(scope+'|'+schema.id+'|view:'+detached.view+'|')))throw Error('미적용 입력을 먼저 적용하세요.');await view.call('closeEditorView',{view:detached.view,id:schema.id});w.el.remove();windows.delete(w.key);renderRetainedEditors();},'독립 뷰 해제 · 공유 초안 유지');w.body.append(release);}
 controls();
}

