const workerEvidence=new Map(),workerSourceSelections=new Map();
function showWorker(worker,refresh=false){
 const scope=current.projectId,key=scope+'|'+worker.id,w=openWindow('worker','Worker 상태 · '+worker.id,580,480,{refresh});w.meta.workerId=worker.id;w.meta.snapshot=JSON.stringify(worker);const checked=workerSourceSelections.get(key)||new Set();
 w.body.innerHTML=`<div class="window-content"><h2>${esc(worker.id)}</h2><p>${esc(worker.ownerHelper||'')} · ● ${esc(worker.status)} · 채택 기록 ${esc(worker.adoptionState||'none')}</p><pre class="consumer-output">${esc(JSON.stringify({goal:worker.goal,stage:worker.stage,completion:worker.completion,progress:worker.progress,blocker:worker.blocker},null,2))}</pre><div class="actions"><button data-operation id="worker-prepare">작업 전 검토</button><button data-operation id="worker-stop">작업 중지</button><button data-operation id="worker-recover">새 복구 작업 검토</button><button data-operation id="worker-adoption-record">채택 기록 검토</button></div><h3>이 Worker의 기록된 미반영 변경</h3><div id="worker-source-list"></div><button data-operation id="worker-review">선택한 변경 Review</button><p>초안과 진행 상태는 유지됩니다. Source Confirm과 작업 채택·완료 기록은 구분합니다. Worker 개별 채팅은 제공하지 않습니다.</p></div>`;
 for(const id of worker.changedIds||[]){const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.dataset.workerSource=id;input.checked=checked.has(id);input.onchange=()=>{const selected=workerSourceSelections.get(key)||new Set();input.checked?selected.add(id):selected.delete(id);workerSourceSelections.set(key,selected);};label.append(input,document.createTextNode(id));$('#worker-source-list').append(label);}
 const run=async(endpoint)=>{if(current.projectId!==scope)throw Error('Worker project changed');await view.call(endpoint,{task:worker.id});};
 $('#worker-prepare').onclick=()=>work(async()=>{await run('prepareWorker');showPreview();},'Worker 전송 전 검토');$('#worker-stop').onclick=()=>work(()=>run('stopWorker'),'Worker 중지 요청됨 · 초안 유지');
 $('#worker-recover').onclick=()=>work(async()=>{await run('recoverWorker');showPreview();},'별도 복구 작업 검토 · 자동 재실행 없음');$('#worker-adoption-record').onclick=()=>work(async()=>{await run('inspectAdoption');showPreview();},'로컬 채택 기록 검토 · 전송 없음');
 $('#worker-review').onclick=()=>work(async()=>{if(dirty||[...schemaInputs.keys()].some(key=>key.startsWith(scope+'|')))throw Error('미적용 입력을 먼저 적용하세요. 입력은 유지됩니다.');const ids=$$('[data-worker-source]:checked').map(input=>input.dataset.workerSource);if(!ids.length)throw Error('검토할 실제 변경을 선택하세요');await view.call('reviewWorker',{task:worker.id,ids,target:targetChoices.get(current.projectId)||current.runTarget});showWorkerReview(worker);},'Worker 변경 검토 · 아직 최종 반영 없음');controls();
}
